import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"开发者工具与 PR","description":"","frontmatter":{},"headers":[],"relativePath":"guide/developer.md","filePath":"guide/developer.md"}'),r={name:"guide/developer.md"};function i(l,t,c,n,p,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="开发者工具与-pr" tabindex="-1">开发者工具与 PR <a class="header-anchor" href="#开发者工具与-pr" aria-label="Permalink to &quot;开发者工具与 PR&quot;">​</a></h1><p>给写程序的同事用。IT 在安全中心打开「<strong>开发者工具</strong>」后，办事模式多出这些能力（这类任务会用后台配置的编程模型）：</p><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td><code>grep</code></td><td>按内容搜代码，支持 <code>**</code> 通配符</td></tr><tr><td><code>multi_edit</code></td><td>一次改一个文件里的多处</td></tr><tr><td><code>git_status</code> / <code>git_diff</code> / <code>git_log</code></td><td>查看状态、改动、历史</td></tr><tr><td><code>git_commit</code></td><td>提交</td></tr><tr><td><code>create_pull_request</code></td><td>推送当前分支并建 PR（每次都要你确认，不能从默认分支建）</td></tr><tr><td><code>pr_status</code> / <code>watch_pull_request</code></td><td>查 PR 状态 / 开始盯一个 PR</td></tr></tbody></table><p>输入框打 <code>/init</code>，AI 会读一遍项目，生成项目说明 <code>FLYKNIT.md</code>，以后的任务都会先参考它。</p><h2 id="git-操作的确认" tabindex="-1">git 操作的确认 <a class="header-anchor" href="#git-操作的确认" aria-label="Permalink to &quot;git 操作的确认&quot;">​</a></h2><p>按子命令和参数定级：查看类直接执行；提交按规则确认；<strong>推送、强制推送、删分支、丢弃修改</strong>等按高危每次确认。</p><h2 id="仓库面板" tabindex="-1">仓库面板 <a class="header-anchor" href="#仓库面板" aria-label="Permalink to &quot;仓库面板&quot;">​</a></h2><p>右侧「文件」标签上方显示当前仓库、分支、未提交改动、领先 / 落后的提交数：</p><ul><li>在 GitHub 上打开仓库或分支、复制分支名、新建或切换分支；</li><li>有未提交的改动或任务正在进行时不允许切换分支。</li></ul><h2 id="盯-pr" tabindex="-1">盯 PR <a class="header-anchor" href="#盯-pr" aria-label="Permalink to &quot;盯 PR&quot;">​</a></h2><p>建好 PR 后可以让它盯着：</p><ul><li>每 50 分钟查一次 CI、冲突、评审和评论，有变化弹通知；</li><li>打开自动修复时，CI 失败、出现冲突或评审要求修改，会在原对话里自动开一轮修复（每个 PR 最多 5 轮，操作照常确认）；</li><li>PR 合并或关闭后自动停止，最多盯 14 天。</li></ul><p>GitHub 操作用的是你电脑上的 <code>gh</code> 和你自己的 GitHub 登录，令牌不经过公司服务器。</p><h2 id="子代理-it-开启后才有" tabindex="-1">子代理（IT 开启后才有） <a class="header-anchor" href="#子代理-it-开启后才有" aria-label="Permalink to &quot;子代理（IT 开启后才有）&quot;">​</a></h2><p>复杂任务里，AI 可以临时开子代理去翻代码、查资料：几个只读子代理可以同时跑，能改东西的一次一个，每个操作照常确认。</p>',15)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
